  57: [{ category: "Words", lines: ["§o’clock", "What time is it?", "What’s the time.", "It’s 3 o’clock.", "Is it 3 o’clock?", "", "§shop", "There are many shops in this street.", "", "§moment", "at the moment", "She is doing the housework at the moment.", "Does she do the housework every day?"] }, { category: "Comprehension", lines: ["Q§1 What's the time?", "A§It's eight o'clock.", "Q§2 Do the children usually go to school by car every day?", "A§Yes, they do.", "Q§3 What are they doing today?", "A§They are going to school on foot.", "Q§4 What does Mrs. Sawyer usually do in the morning.", "A§She usually stays at home.", "Q§5 What is she doing this morning?", "A§She's going to the shops.", "Q§6 Who usually drinks tea in the living room?", "A§Mrs. Sawyer does.", "Q§7 Where is she drinking tea this afternoon?", "A§In the garden.", "Q§8 When do the children usually do their homework?", "A§In the evening.", "Q§9 What are they doing at the moment?", "A§They're playing in the garden.", "Q§10 What is Mr. Sawyer doing tonight?", "A§He's reading an interesting book."] }, { category: "Asking questions", lines: ["Q§1 Ask me if the children go to school by car.", "Q§How...?", "A§Do the Children go to school by car?", "A§How do the children go to school?", "Q§2 Ask me if Mrs. Sawyer is going to the shops.", "Q§Where...?", "A§Is Mrs. Sawyer going to the shops?", "A§Where is Mrs. Sawyer going?"] }],
