  99: [{ category: "Grammar", lines: ["哔哩哔哩 胶囊助学计划", "宾语从句", "定义：⼀个句⼦充当宾语", "这个句⼦叫宾语从句", "主语 + v. + (that) + 句⼦", "I hope that you’ve got some money. L79", "I believe that this house is for sale. L89", "I think that they’ll move in the day after tomorrow. L91", "主语 + v. + (that) + 句⼦", "v. : think/believe/hope/say/understand/know", "I think that you are right.", "He believes that they will help him.", "I hope that the food is safe here.", "She says that she will help you.", "We understand that we mustn’t talk in the library.", "Describe your Dad/Mom/best friend/GF/BF.....", "I know that he is 29.", "I know that he likes ice cream.", "I know that he lives in Beijing.", "I know that she/he will be a good wife/husband.", "I know that he can play basketball.", "商量做饭(两个菜)，讨论买什么东⻄。", "I think that we need...."] }, { category: "Words", lines: ["§ow", "", "§slip v.", "I slipped.", "Did you slip?", "How did you slip?", "", "§fall fell fallen v. downstairs", "I fell downstairs.", "Did you fall downstairs?", "Be careful, don’t fall down.", "", "§hurt v. back", "I hurt my back yesterday.", "She hurts her back every summer.", "Why does she hurt her back every summer?", "", "§stand up", "sit down"] }],
