  101: [{ category: "Grammar", lines: ["直接引语 - 间接引语", "The doctor says, “I will come at once.”", "The doctor says that he will come at once.", "1. 引号去掉", "2. 转换⼈称", "3. 添加引导词 that", "He says “I can do it .”", "He says that he can do it .", "“I have just arrived in Scotland.” says Leo.", "Leo says that he has just arrived in Scotland.", "He says, “I feel tired.”", "He says that he feels tired.", "They say, “we will win the game.”", "They say that they will win the game.", "He says that he must wait for his friends.", "结论：间接引语属于宾语从句"] }, { category: "Words", lines: ["§Scotland", "Scotland", "England", "Wales /weilz/", "Northern Ireland / ˈ aiələnd/", "Have you ever been to Scotland?", "Where’s John? He has gone to Scotland.", "They will fly to Scotland next week.", "", "§card n.", "postcard", "business card", "ID card", "We bought some postcards yesterday.", "He buys a postcard every summer.", "Do you have a business card?", "Show me your ID card please.", "", "§youth hostel association", "YHA", "", "§soon", "He will write a letter soon.", "Will he write a letter soon?", "when/why/who...", "", "§write wrote written", "write to sb.", "You haven't written to me for a long time!", "I wrote a letter to him last week.", "I’m gonna write you a letter soon."] }, { category: "Comprehension", lines: ["Q§1 What does Grandmother want Penny to read to her?", "A§Jimmy's Card.", "Q§2 Where is Jimmy?", "A§He's in Scotland.", "Q§3 Has Jimmy been in Scotland for a long time?", "A§No, he hasn't.", "Q§4 Where does he say he's staying?", "A§At a Youth Hostel.", "Q§5 Does he say he'll write a letter soon?", "A§Yes, he does.", "Q§6 What else does he say?", "A§He says he hopes they are all well.", "Q§7 Why does Grandmother ask Penny to speak up?", "A§Because she can't hear very well.", "Q§8 How much can Jimmy write on a card?", "A§Not very much."] }, { category: "Asking questions", lines: ["Q§1 Ask me if Jimmy has just arrived in Scotland.", "Q§Where ...?", "A§Has Jimmy just arrived in Scotland?", "A§Where has Jimmy just arrived?", "Q§2 Ask me if he's staying at a Youth Hostel.", "Q§Where ...?", "A§Is he staying at a Youth Hostel?", "A§Where is he staying?", "Q§3 Ask me if he says he'll write a letter soon.", "Q§What else ...?", "A§Does he say he'll write a letter soon?", "A§What else does he say?", "Q§4 Ask me if Grandmother can hear her.", "Q§Why can't ...?", "A§Can Grandmother hear her?", "A§Why can't Grandmother hear her?", "Q§5 Asks me if he hopes we are all well.", "Q§What ...?", "A§Does he hope we are all well?", "A§What does he hope?"] }],
