  115: [{ category: "Grammar", lines: ["哔哩哔哩 胶囊助学计划", "every no", "everyone no one", "everybody nobody", "everything nothing", "everywhere nowhere", "any some", "anyone someone", "anybody somebody", "anything something", "anywhere somewhere"] }, { category: "Words", lines: ["§knock v.", "Someone is knocking at the door.", "Who is knocking at the door?", "Did you knock at the door?", "", "§quiet adj.", "Be quiet.", "", "§impossible adj.", "im+possible", "Everything is possible.", "Nothing is impossible.", "", "§invite v.", "They invited me to dinner.", "Did they invite you to dinner?", "Why did they invite you to dinner?", "", "§lemonade n.", "give me some lemonade.", "This lemonade is the best I’ve ever tasted.", "This lemonade is as good as that one.", "", "§joke v.", "She is joking.", "Is she joking?", "You can’t joke about this."] }, { category: "Comprehension", lines: ["Q§1 Why does Jim think that there is no one at home?", "A§Because everything is very quiet.", "Q§2 Will Jim go away or will he knock again?", "A§He'll knock again.", "Q§3 Why does Helen think it is impossible that there's no one at home?", "A§Because Carol and Tom invited them to lunch.", "Q§4 What does Helen ask Jim to do?", "A§She asks Jim to look through the window.", "Q§5 Can Jim see anything?", "A§No, he can't.", "Q§6 Where do they find their friends?", "A§In the garden.", "Q§7 Why is everyone in the garden?", "A§Because everybody wants to have lunch out there.", "Q§8 What would Jim like to drink?", "A§He'd like a glass of beer.", "Q§9 Is there any beer left?", "A§Yes, there is."] }, { category: "Asking questions", lines: ["Q§1 Ask me if Jim will knock at the door.", "Q§Who...?", "A§Will Tim knock at the door?", "A§Who will knock at the door?", "Q§2 Ask me if Tom and Carol invited them to lunch.", "Q§Who...?", "A§Did Tom and Carol invite them to lunch?", "A§Who invited them to lunch?", "Q§3 Ask me if everyone is in the garden.", "Q§Where...?", "A§Is everyone in the garden?", "A§Where is everyone?", "Q§4 Ask me if Jim can have some lemonade to drink.", "Q§What...?", "A§Can Jim have some lemonade to drink?", "A§What can Jim have to drink?", "Q§5 Ask if Jim wants any beer.", "Q§What...?", "A§Does Jim want any beer?", "A§What does Jim want?"] }],
